mapper.select:


     and materialCode = #{materialCode}
     and barCodeStr like concat('%', #{barCodeStr}, '%')
     and scanDate >= #{startTime}
     and scanDate <= DATEADD(day, 1, #{endTime})
     and scanMachine = #{scanMachine}
     and scanIPAddress = #{scanIPAddress}
     and duplicateFlag = #{duplicateFlag}

order by scanDate desc

SELECT COUNT(*)
FROM dbo.vwBYDLabelScan_Select s
WHERE s.materialCode = #{materialCode}
AND EXISTS (
    SELECT 1
    FROM dbo.vwBYDLabelPrint_Select p
    WHERE p.materialCode = s.materialCode
    AND p.barCodeStr = s.barCodeStr
    AND p.labelPrintDateTime >= #{labelStartTime}
    AND p.labelPrintDateTime < DATEADD(day, 1, #{labelEndTime}) 
     and p.labelNumber = #{labelNumber}
     and p.labelNumber >= #{labelNumberStart}
     and p.labelNumber <= #{labelNumberEnd}
)

SELECT COUNT(DISTINCT p.barCodeStr)
FROM dbo.vwBYDLabelPrint_Select p
WHERE p.materialCode = #{materialCode}
AND p.labelPrintDateTime >= #{labelStartTime}
AND p.labelPrintDateTime < DATEADD(day, 1, #{labelEndTime}) 
 and p.labelNumber = #{labelNumber}
 and p.labelNumber >= #{labelNumberStart}
 and p.labelNumber <= #{labelNumberEnd}
AND NOT EXISTS (
    SELECT 1
    FROM dbo.vwBYDLabelScan_Select s
    WHERE s.materialCode = p.materialCode
    AND s.barCodeStr = p.barCodeStr
);
